-- PT143-S1-Q2. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT143-S1-Q2$batch09$ AND q.stimulus=$batch09$Popular science publications that explain new developments in science face a dilemma. In order to reach a wide audience, these publications must rely heavily on metaphorical writing, which usually fails to convey the science accurately. If the writing is more rigorous, they get the science right but fail to reach a wide audience. These publications should therefore give up trying to explain new developments in science to a wide audience.$batch09$ AND q.prompt=$batch09$Which one of the following principles, if valid, most helps to justify the reasoning in the argument?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT143-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch09$a1b43dc1-8408-43a8-b320-f0eb3074fbe2$batch09$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch09$a1b43dc1-8408-43a8-b320-f0eb3074fbe2$batch09$) <> 5 THEN RAISE EXCEPTION 'Explanation changed: PT143-S1-Q2'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Popular science publications should give up trying to explain new science to a wide audience.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$To reach a wide audience, they have to rely on metaphor, which usually gets the science wrong. If they write more rigorously, they get the science right but lose the wide audience.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$This is a tradeoff with two options. Reach a wide audience and be inaccurate, or be accurate and reach fewer people. The author picks accuracy. Nothing in the evidence says which matters more. That ranking is what the principle has to supply.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Being accurate matters more than reaching a wide audience.$batch09$)) v(position,label,body) WHERE e.id=$batch09$a1b43dc1-8408-43a8-b320-f0eb3074fbe2$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
